command:
// Force World Migration — Judge only.
// Resets the schema version of all world documents to the chosen value and re-runs ACKS migrations.

if (!game.user.isGM) {
  return ui.notifications.warn(game.i18n.localize("ACKS.Macro.ForceMigration.GMOnly"));
}

const { DialogV2 } = foundry.applications.api;

const data = await DialogV2.input({
  window: { title: "ACKS.Macro.ForceMigration.Title", icon: "fa-solid fa-database" },
  content: `
    <p>${game.i18n.localize("ACKS.Macro.ForceMigration.Hint")}</p>
    <div class="form-group">
      <label for="acks-migration-from">${game.i18n.localize("ACKS.Macro.ForceMigration.From")}</label>
      <div class="form-fields">
        <input id="acks-migration-from" type="number" name="from" value="0" min="0" step="1" required autofocus>
      </div>
    </div>`,
  ok: { label: "ACKS.Macro.ForceMigration.Execute", icon: "fa-solid fa-play" },
  buttons: [{ action: "cancel", label: "Cancel", icon: "fa-solid fa-xmark", callback: () => null }],
});

if (!data) return; // Cancel pressed or dialog closed

const from = Math.max(0, Math.floor(Number(data.from) || 0));
await game.acks.debug.forceWorldMigration(from);
